import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzDatePickerModule } from 'ng-zorro-antd/date-picker';
import { HrmControl } from '../shared/hrm-control';
import { HrmSize, HrmStatus, toNzStatus } from './hrm-input';

const toNz = (s: HrmSize) => (s === 'sm' ? 'small' : s === 'lg' ? 'large' : 'default');

/** hrm-range-picker — CVA [Date, Date], bọc nz-range-picker. */
@Component({
  selector: 'hrm-range-picker',
  imports: [FormsModule, NzDatePickerModule],
  template: `
    <nz-range-picker
      style="width:100%"
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzFormat]="format()"
      [nzDisabled]="disabled()"
      [nzSize]="toNz(size())"
      [nzStatus]="toNzStatus(status())"
      [nzShowTime]="showTime()"
      [nzDisabledDate]="disabledDate()"></nz-range-picker>
  `,
  host: { class: 'hrm-range-picker', '[class.hrm-status-success]': "status() === 'success'" },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmRangePicker), multi: true }],
})
export class HrmRangePicker extends HrmControl<Date[]> {
  readonly format = input('dd/MM/yyyy');
  readonly size = input<HrmSize>('md');
  readonly status = input<HrmStatus>('');
  readonly showTime = input(false);
  /** Chặn ngày không cho chọn — hàm thuần (d) => boolean, không chứa text hiển thị. */
  readonly disabledDate = input<((d: Date) => boolean) | undefined>(undefined);
  protected readonly toNz = toNz;
  protected readonly toNzStatus = toNzStatus;
}
